    if (!ctx) return; const t = ctx.currentTime, set = (g, v) => g.gain.setTargetAtTime(v, t, .05);
    set(bus.master, S.master); set(bus.fx, S.fx.on ? 1 : 0); set(bus.voice, S.voice.on ? S.voice.vol : 0);
    if (!speaking) set(bus.music, S.music.on ? S.music.vol : 0);
