function fitTable() {
  const stage = document.querySelector('#tb');
  const table = document.querySelector('#tw');
  const game = document.querySelector('#gm');
  const topSeat = document.querySelector('#s2');
  if (!stage || !table || !topSeat || !game || !game.classList.contains('on')) return;
  const width = stage.clientWidth, height = stage.clientHeight;
  if (width < 10 || height < 10) return;
  const landscape = innerWidth > innerHeight && innerHeight < 600;
  const compact = height < 260;
  table.dataset.compact = compact ? 'true' : 'false';
  table.dataset.landscape = landscape ? 'true' : 'false';

  // Preserve every fan/back node for the animation hook; CSS shows its lead back.
  table.querySelectorAll('.seat .fan').forEach(fan => {
    const count = fan.querySelectorAll('.cb').length;
    fan.dataset.count = String(count);
    fan.setAttribute('aria-label', count + ' أوراق');
  });

  // The header is measured after the horizontal top-seat CSS is applied.
  const topHeight = Math.ceil(topSeat.getBoundingClientRect().height);
  const topReserve = topHeight + (compact ? 7 : 10);
  const available = Math.max(36, height - topReserve - 4);
  const rugWidth = Math.min(width * .82, 540);
  const rugHeight = Math.min(rugWidth * 1.25, available);
  // Center surplus vertical space, but spend none on a duplicate human seat.
  const tableTop = topReserve + Math.max(0, available - rugHeight) * .45;
  const seatOutset = Math.min(36, Math.max(0, (width - rugWidth) / 2 - 4));
  table.style.setProperty('--table-w', rugWidth.toFixed(2) + 'px');
  table.style.setProperty('--table-h', rugHeight.toFixed(2) + 'px');
  table.style.setProperty('--table-top', tableTop.toFixed(2) + 'px');
  table.style.setProperty('--seat-outset', seatOutset.toFixed(2) + 'px');
  topSeat.style.top = -(topHeight + (compact ? 4 : 6)) + 'px';

  // A compact central cross, not four tiny cards at the carpet's corners.
  // Height bound includes the rotated side cards; it may fall below 55 only
  // on a genuinely short landscape stage. Never change the hand's --cw.
  const playWidth = Math.min(80, rugWidth * .23, rugHeight / 2.6);
  document.documentElement.style.setProperty('--tw', playWidth.toFixed(2) + 'px');
  if (window.QaidRank && typeof QaidRank.placeSeats === 'function') QaidRank.placeSeats();
  if (typeof placeTrickPile === 'function') placeTrickPile();
}
addEventListener('resize', fitTable);
