  if (st.phase==='QABLAK') return 'قبلك؟ أولوية الصن لمن سبق';
  if (st.phase==='FLIP') return st.floorRank===7?'الأرض إكة — يمين الموزّع فقط يستطيع قلب الحكم صن':'قبل الدبل: تقدر تقلب الحكم إلى صن';
