async function hostSawa(player, token) {
  ensure(token);
  if (!R || R.phase !== 'play' || (R.trick && R.trick.length)) { say('سوا قبل أول ورقة من الأكلة'); return false; }
  let claim;
  try { claim = Baloot.claimAll(R.h, player, R.mode, R.T, 90000, { open: R.open }); }
  catch (error) { say('تعذر التحقق من سوا'); return false; }
  if (claim.result !== true && claim.result !== false) { say('لم يكتمل إثبات سوا'); return false; }
  const team = player % 2;
  if (claim.result === true) {
    R.pts[team] += R.h.flat().reduce((sum, c) => sum + val(c), 0) + 10;
    R.tk[team] += R.h[player].length;
    R.h = [[], [], [], []];
    R.n = 8;
    say(NM(player) + ': سوا صحيحة');
    log(NM(player) + ': سوا صحيحة — المعلن يأخذ جميع الباقي');
  } else {
    R.forced = { winner: 1 - team, tag: 'سوا خاطئة' };
    say(NM(player) + ': سوا خاطئة');
    log(NM(player) + ': سوا خاطئة');
  }
  await showSawaDrop(token, player);
  renderHand();
  await wait(600, token);
  await endRound(token);
  return true;
}
