function theme(t) {P.theme=['trad','dark','light'].includes(t)?t:'trad';document.documentElement.dataset.theme=P.theme;save();try{parent.postMessage({source:'qayd-theme',theme:P.theme},location.origin);}catch(e){}}

const QAYD_VERSION = '2026.11';
const SET_TITLES = {account:'الحساب',sound:'الصوت',look:'المظهر',play:'اللعب',privacy:'الخصوصية',notes:'التنبيهات',lang:'اللغة',access:'الوضوح',help:'الدعم'};
function fmtNum(n) { return Number(n||0).toLocaleString(prefs().nums==='arab' ? 'ar' : 'en'); }
function prefs() {
  const d = { text:'md', contrast:0, reduceMotion:0, reduceFx:0, vibrate:1, hints:1, matchInfo:1, tableFx:1, showOnline:1, invites:1, bg:'majlis', nums:'latn', blocked:[],
    notif:{ invite:1, friend:1, accept:1, award:1, level:1, event:1, alert:1 } };
  const cur = (P.prefs && typeof P.prefs === 'object') ? P.prefs : {};
  P.prefs = Object.assign({}, d, cur, { friendRequests: cur.friendRequests === 0 ? 0 : 1 });
  P.prefs.notif = Object.assign({}, d.notif, cur.notif || {});
  if (!Array.isArray(P.prefs.blocked)) P.prefs.blocked = [];
  return P.prefs;
}
function pushPrefs() {
  const p = prefs();
  try { parent.postMessage({ source:'qayd-ui', prefs:{ showOnline:p.showOnline!==0, invites:p.invites!==0 && p.notif.invite!==0, friend:p.notif.friend!==0, accept:p.notif.accept!==0, friendRequests:p.friendRequests!==0, blocked:p.blocked.slice() } }, location.origin); } catch (e) {}
}
function applyPrefs() {
  const p = prefs();
  const root = document.documentElement;
  root.dataset.text = p.text || 'md';
  root.dataset.contrast = p.contrast ? '1' : '0';
  root.dataset.bg = p.bg || 'majlis';
  root.dataset.nums = p.nums || 'latn';
  root.dataset.info = p.matchInfo === 0 ? '0' : '1';
  root.lang = 'ar';
  root.dir = 'rtl';
  root.classList.toggle('qaid-still', !!p.reduceMotion);
  if (!document.getElementById('qaid-still-style')) {
    const st = document.createElement('style'); st.id = 'qaid-still-style';
    st.textContent = 'html.qaid-still *{animation-duration:.01ms!important;transition-duration:.01ms!important}';
    document.head.appendChild(st);
  }
  window.__qaydVibrate = !!p.vibrate;
  window.__qaydHints = p.hints !== 0;
  window.__qaydSlamFx = p.tableFx !== 0 && !p.reduceFx;
  pushPrefs();
}
