function switchRow(host, key, label, desc, read, write) {
  const row = document.createElement('div'); row.className = 'set-row';
  const copy = document.createElement('div');
  copy.innerHTML = '<b></b><p></p>';
  copy.querySelector('b').textContent = label;
  copy.querySelector('p').textContent = desc;
  const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'sw';
  btn.innerHTML = '<i></i>';
  const paint = () => { const on = !!read(); btn.classList.toggle('on', on); btn.setAttribute('aria-pressed', on ? 'true' : 'false'); btn.setAttribute('aria-label', label); };
  btn.onclick = () => { write(!read()); paint(); commitPrefs(); sfx('click'); };
  paint(); row.append(copy, btn); host.append(row);
}
