    const meta = document.createElement('div');
    const pct = info.maxed || !info.need ? 100 : Math.max(0, Math.min(100, Math.round((info.xp / info.need) * 100)));
    meta.innerHTML = '<b></b><small></small><span class="set-xp"><i></i></span>';
